import { Meta, StoryObj } from "@storybook/react";
import CalendarFooter from "./calendar-footer";
import { action } from "storybook/actions";
import { PartOfDay } from "@parksandresorts/webapiproxy-types";
import { expect, within } from "storybook/test";
import labels from "@/core/labels/labels";
import { initLabels } from "@/core/labels/i18n";

const meta = {
  title: "Primitives/Daily Schedule/Calendar Footer",
  component: CalendarFooter,
} satisfies Meta<typeof CalendarFooter>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    selectedDate: new Date("2024-10-08"),
    openingHours: {
      closingTime: "22.00",
      date: new Date("2024-10-08"),
      openingTime: "10.00",
      passes: [],
    },
    nextOpenDay: new Date("2024-10-09"),
    onChangeToNextOpenDate: action("Click onchange"),
    calendarOpeningTimes: "Öppettider",
    contentfulLabelId: "Hej",
  },
};

export const Closed: Story = {
  args: {
    ...Primary.args,
    openingHours: undefined,
  },
};

const gapLabel = labels.sv.parkClosesBetweenPasses;
const splittedGapLabel = gapLabel.split(/\s*\{\{.*?\}\}\s*/); //Split on variables like "{{firstPassTo}}"
const firstPartOfGapLabel = splittedGapLabel[0];

export const PassesWithGap: Story = {
  args: {
    ...Primary.args,
    openingHours: {
      closingTime: "22.00",
      date: new Date("2024-10-08"),
      openingTime: "10.00",
      passes: [
        {
          partOfDay: PartOfDay.MORNING,
          from: "2024-10-08T08:00:00.000Z",
          to: "2024-10-08T14:00:00.000Z",
        },
        {
          partOfDay: PartOfDay.AFTERNOON,
          from: "2024-10-08T14:30:00.000Z",
          to: "2024-10-08T20:30:00.000Z",
        },
      ],
    },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    expect(canvas.getByText(firstPartOfGapLabel, { exact: false })).toBeInTheDocument();
  },
};

export const PassesWithoutGap: Story = {
  args: {
    ...Primary.args,
    openingHours: {
      closingTime: "22.00",
      date: new Date("2024-10-08"),
      openingTime: "10.00",
      passes: [
        {
          partOfDay: PartOfDay.MORNING,
          from: "2024-10-08T08:00:00.000Z",
          to: "2024-10-08T14:00:00.000Z",
        },
        {
          partOfDay: PartOfDay.AFTERNOON,
          from: "2024-10-08T14:00:00.000Z", //When from time is the same as previous pass' end time, there is no gap between passes
          to: "2024-10-08T20:30:00.000Z",
        },
      ],
    },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    expect(canvas.queryByText(firstPartOfGapLabel, { exact: false })).toBeNull();
  },
};

export const MultiplePasses: Story = {
  args: {
    ...Primary.args,
    openingHours: {
      closingTime: "22.00",
      date: new Date("2024-10-08"),
      openingTime: "10.00",
      passes: [
        {
          partOfDay: PartOfDay.MORNING,
          from: "2024-10-08T08:00:00.000Z",
          to: "2024-10-08T14:00:00.000Z",
        },
        {
          partOfDay: PartOfDay.AFTERNOON,
          from: "2024-10-08T14:30:00.000Z",
          to: "2024-10-08T18:00:00.000Z",
        },
        {
          partOfDay: PartOfDay.NIGHT,
          from: "2024-10-08T18:30:00.000Z",
          to: "2024-10-08T20:00:00.000Z",
        },
      ],
    },
  },
  //When we have three or more passes we should never show them, instead we show a simple opening hours text
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    expect(canvas.queryByText(labels.sv.morning, { exact: false })).toBeNull();
    expect(canvas.queryByText(labels.sv.afternoon, { exact: false })).toBeNull();
    expect(canvas.queryByText(labels.sv.night, { exact: false })).toBeNull();
  },
};

export const HiddenLabelShowOpeningHours: Story = {
  args: {
    ...Primary.args,
    openingHours: {
      closingTime: "22.00",
      date: new Date("2024-10-08"),
      openingTime: "10.00",
      passes: [
        {
          partOfDay: PartOfDay.MORNING,
          from: "2024-10-08T08:00:00.000Z",
          to: "2024-10-08T14:00:00.000Z",
        },
        {
          partOfDay: PartOfDay.AFTERNOON,
          from: "2024-10-08T14:30:00.000Z",
          to: "2024-10-08T20:30:00.000Z",
        },
      ],
    },
  },
  render: (args) => {
    const modifiedLabels = {
      ...labels,
      sv: {
        ...labels.sv,
        morning: "HIDDEN_LABEL",
      },
      nn: {},
    };

    initLabels("sv", modifiedLabels);

    return <CalendarFooter {...args} />;
  },

  // When we have 2 passes, and hides one of them, it should behave as if we only had 1 pass and show the opening hours
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    expect(canvas.queryByText(labels.sv.morning, { exact: false })).not.toBeInTheDocument();
    expect(canvas.queryByText(labels.sv.afternoon, { exact: false })).not.toBeInTheDocument();
    expect(canvas.queryByText("Öppet 10.00 - 22.00", { exact: false })).toBeInTheDocument();
  },
};

export const HiddenLabelShowPartOfDay: Story = {
  args: {
    ...HiddenLabelShowOpeningHours.args,
    openingHours: {
      closingTime: "22.00",
      date: new Date("2024-10-08"),
      openingTime: "10.00",
      passes: [
        {
          partOfDay: PartOfDay.MORNING,
          from: "2024-10-08T08:00:00.000",
          to: "2024-10-08T14:00:00.000",
        },
        {
          partOfDay: PartOfDay.DAY,
          from: "2024-10-08T08:00:00.000",
          to: "2024-10-08T14:00:00.000",
        },
        {
          partOfDay: PartOfDay.AFTERNOON,
          from: "2024-10-08T14:30:00.000",
          to: "2024-10-08T20:30:00.000",
        },
      ],
    },
  },
  render: HiddenLabelShowOpeningHours.render,

  // When we have 3 passes, and hides one of them, it should behave same as `PassesWithGap`
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    expect(canvas.queryByText("Dag 08:00 - 14:00", { exact: false })).toBeInTheDocument();
    expect(canvas.queryByText("Eftermiddag 14:30 - 20:30", { exact: false })).toBeInTheDocument();

    expect(canvas.queryByText(labels.sv.morning, { exact: false })).not.toBeInTheDocument();
    expect(canvas.queryByText("Öppet 10.00 - 22.00", { exact: false })).not.toBeInTheDocument();
  },
};
